def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys[i] = values[i] on the defaults mode=fast and level=3. Return mode, level, then the other keys' values in the order given."""
    pre keys.len() == values.len()
    post out.len() >= 2
    ex settings(keys=[], values=[]) == ["fast", "3"]
    ex settings(keys=["mode", "color"], values=["slow", "red"]) == ["slow", "3", "red"]
    ex settings(keys=["level", "level"], values=["1", "2"]) == ["fast", "2"]
    out_map: dict[str, str] = {"mode": "fast", "level": "3"}
    for i in range(keys.len()):
        out_map[keys[i]] = values[i]
    mode = out_map.get("mode") else "fast"
    level = out_map.get("level") else "3"
    result: list[str] = [mode, level]
    seen: dict[str, bool] = {}
    for k in keys:
        if k != "mode" and k != "level" and k not in seen:
            seen[k] = True
            result.append(out_map.get(k) else "")
    return result
